import logging

logging.basicConfig(level=logging.INFO, format="%(levelname)s %(name)s: %(message)s")
log = logging.getLogger("etl")


def cargar(filas):
    if not filas:
        raise ValueError("no hay filas para procesar")
    log.info("cargadas %d filas", len(filas))
    return filas


def limpiar(filas):
    validas = [fila for fila in filas if fila.get("precio")]
    descartadas = len(filas) - len(validas)
    if descartadas:
        log.warning("filas descartadas: %d", descartadas)
    return validas


try:
    datos = cargar([{"precio": 10}, {"precio": None}, {"precio": 25}])
    print(limpiar(datos))
except ValueError as error:
    log.error("ETL abortado: %s", error)

