import pytest

def es_mayor_de_edad(edad: int) -> bool:
    return edad >= 18

@pytest.mark.parametrize("edad, esperado", [(17, False), (18, True), (65, True)])
def test_limite(edad, esperado):
    assert es_mayor_de_edad(edad) is esperado

def test_tipo_incorrecto():
    with pytest.raises(TypeError):
        es_mayor_de_edad("18")
